// File:   aes2_wrapper.sv


module aes2_wrapper #(
    parameter int unsigned AXI_ADDR_WIDTH = 64,
    parameter int unsigned AXI_DATA_WIDTH = 64,
    parameter int unsigned AXI_ID_WIDTH   = 10
)(
           clk_i,
           rst_ni,
           reglk_ctrl_i,
           acct_ctrl_i,
           debug_mode_i,
           axi_req_i, 
           axi_resp_o,
           rst_11
       );

    input  logic                   clk_i;
    input  logic                   rst_ni;
    input logic [7 :0]             reglk_ctrl_i; // register lock values
    input logic                    acct_ctrl_i;
    input logic                    debug_mode_i;
    input  ariane_axi::req_t       axi_req_i;
    output ariane_axi::resp_t      axi_resp_o;
    input logic rst_11;

// internal signals
logic start;
logic ct_valid;

logic [31:0] p_c [0:3];
logic [31:0] state [0:3];
logic [31:0] key0 [0:3]; 
logic [31:0] key1 [0:3]; 
logic [31:0] key2 [0:3]; 

logic [1:0] key_sel; 

logic   [127:0] state_big;
logic   [127:0] dii_data   ;
logic   [127:0] cii_K;
logic   [127:0] cii_K0, cii_K1, cii_K2 ;  
logic   [127:0] ct;


// signals from AXI 4 Lite
logic [AXI_ADDR_WIDTH-1:0] address;
logic                      en, en_acct;
logic                      we;
logic [63:0] wdata;
logic [63:0] rdata;

assign state_big = {state[0], state[1], state[2], state[3]};
assign dii_data = {p_c[0], p_c[1], p_c[2], p_c[3]};
assign cii_K0    = debug_mode_i ? 128'b0 : {key0[0], key0[1], key0[2], key0[3]}; 
assign cii_K1    = debug_mode_i ? 128'b0 : {key1[0], key1[1], key1[2], key1[3]}; 
assign cii_K2    = debug_mode_i ? 128'b0 : {key2[0], key2[1], key2[2], key2[3]};

///////////////////////////////////////////////////////////////////////////
    // -----------------------------
    // AXI Interface Logic
    // -----------------------------
    axi_lite_interface #(
        .AXI_ADDR_WIDTH ( AXI_ADDR_WIDTH ),
        .AXI_DATA_WIDTH ( AXI_DATA_WIDTH ),
        .AXI_ID_WIDTH   ( AXI_ID_WIDTH    )   
    ) axi_lite_interface_i (
        .clk_i      ( clk_i      ),
        .rst_ni     ( rst_ni     ),
        .axi_req_i  ( axi_req_i  ),
        .axi_resp_o ( axi_resp_o ),
        .address_o  ( address    ),
        .en_o       ( en_acct    ),
        .we_o       ( we         ),
        .data_i     ( rdata      ),
        .data_o     ( wdata      )
    );

    assign en = en_acct && acct_ctrl_i; 


// Implement APB I/O map to AES interface
// Write side
always @(posedge clk_i)
    begin
        if (~(rst_ni && ~rst_11))
            begin
                start <= 0;
                p_c[0] <= 0;
                p_c[1] <= 0;
                p_c[2] <= 0;
                p_c[3] <= 0;
                state[0] <= 0;
                state[1] <= 0;
                state[2] <= 0;
                state[3] <= 0;
                
            end
        else if(en && we)
            case(address[8:3]) // different signals will have a different address base.
                0:
                    start  <= reglk_ctrl_i[1] ? start  : wdata[0];
                1:
                    p_c[3] <= reglk_ctrl_i[3] ? p_c[3] : wdata[31:0];
                2:
                    p_c[2] <= reglk_ctrl_i[3] ? p_c[2] : wdata[31:0];
                3:
                    p_c[1] <= reglk_ctrl_i[3] ? p_c[1] : wdata[31:0];
                4:
                    p_c[0] <= reglk_ctrl_i[3] ? p_c[0] : wdata[31:0];
                5:
                    key0[3] <= reglk_ctrl_i[5] ? key0[3] : wdata[31:0];
                6:                                        
                    key0[2] <= reglk_ctrl_i[5] ? key0[2] : wdata[31:0];
                7:                                        
                    key0[1] <= reglk_ctrl_i[5] ? key0[1] : wdata[31:0];
                8:
                    key0[0] <= reglk_ctrl_i[5] ? key0[0] : wdata[31:0];
                14:
                    state[3] <= reglk_ctrl_i[3] ? state[3] : wdata[31:0];
                15:                                        
                    state[2] <= reglk_ctrl_i[3] ? state[2] : wdata[31:0];
                16:                                        
                    state[1] <= reglk_ctrl_i[3] ? state[1] : wdata[31:0];
                17:
                    state[0] <= reglk_ctrl_i[3] ? state[0] : wdata[31:0];                   
                18:                                       
                    key1[3] <= reglk_ctrl_i[5] ? key1[3] : wdata[31:0];
                19:                                       
                    key1[2] <= reglk_ctrl_i[5] ? key1[2] : wdata[31:0];
                20:                                       
                    key1[1] <= reglk_ctrl_i[5] ? key1[1] : wdata[31:0];
                21:                                        
                    key1[0] <= reglk_ctrl_i[5] ? key1[0] : wdata[31:0];
                22:                                       
                    key2[3] <= reglk_ctrl_i[5] ? key2[3] : wdata[31:0];
                23:                                       
                    key2[2] <= reglk_ctrl_i[5] ? key2[2] : wdata[31:0];
                24:                                       
                    key2[1] <= reglk_ctrl_i[5] ? key2[1] : wdata[31:0];
                25:                            
                    key2[0] <= reglk_ctrl_i[5] ? key2[0] : wdata[31:0];
                26: 
                    key_sel <= reglk_ctrl_i[1] ? key_sel : wdata[31:0];
                default:
                    ;
            endcase
    end // always @ (posedge wb_clk)

// Implement MD5 I/O memory map interface
// Read side
//always @(~write)
always @(*)
    begin
      rdata = 64'b0; 
      if (en) begin
        rdata = key0[address[8:3]]; 
        case(address[8:3])
            0:
                rdata = reglk_ctrl_i[0] ? 'b0 : {31'b0, start};
            1:
                rdata = reglk_ctrl_i[2] ? 'b0 : p_c[3];
            2:
                rdata = reglk_ctrl_i[2] ? 'b0 : p_c[2];
            3:
                rdata = reglk_ctrl_i[2] ? 'b0 : p_c[1];
            4:
                rdata = reglk_ctrl_i[2] ? 'b0 : p_c[0];
            9:
                rdata = reglk_ctrl_i[6] ? 'b0 : {31'b0, ct_valid};
            10:
                rdata = reglk_ctrl_i[4] ? 'b0 : ct[31:0];
            11:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ct[63:32];
            12:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ct[95:64];
            13:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ct[127:96];
            default:
                if (ct_valid)
                    rdata = 32'b0;
        endcase
      end // if
    end // always @ (*)


// select the proper key

assign cii_K = key_sel[1] ? cii_K2 : ( key_sel[0] ? cii_K1 : cii_K0 );

aes2_interface aes2_interface(
    .clk(clk_i),
    .iv(state_big),
    .rst(rst_ni && ~rst_11),
    .start(start),
    .cii_K(cii_K),
    .input_pc(dii_data),
    
    .Out_data_final(ct),
    .ct_valid_out(ct_valid)
    );

endmodule
// File:   timescale.v
`timescale 1ns / 10ps
// File:   aes2_interface.v
module aes2_interface(
	clk,
	rst,
	input_pc,
	iv,
	cii_K,
	start,
	ct_valid_out,
	Out_data_final
);

parameter s0 = 4'd0;
parameter s1 = 4'd1;
parameter s2 = 4'd2;
parameter s3 = 4'd3;
parameter s4 = 4'd4;
parameter s5 = 4'd5;
parameter s6 = 4'd6;
parameter s7 = 4'd7;
parameter s8 = 4'd8;
parameter s9 = 4'd9;
parameter s10 = 4'd10;
parameter s11 = 4'd11;
parameter s12 = 4'd12;
parameter s13 = 4'd13;
parameter s14 = 4'd14;
parameter s15 = 4'd15;


input			start;
input 			clk;
input			rst;
input 	[127:0]	cii_K;
input 	[127:0]	input_pc;
input	[127:0] iv;
output reg [127:0] Out_data_final;
output reg ct_valid_out = 0;

wire dii_data_not_ready;
wire [3:0] Out_data_size;
wire t_v;
wire Out_last_word;
wire [127:0] Out_data;
wire ct_valid;

reg [3:0] state = s0;
reg rst_internal = 0;
reg [127:0] dii_data = 0;
reg dii_data_vld = 0;
reg dii_data_type = 0;
reg dii_last_word = 0;
reg [3:0] dii_data_size = 0;
reg cii_IV_vld = 0;
reg cii_ctl_vld = 0;
reg [4:0] ctr = 0;


always @(posedge clk)
    begin
        if(~rst)
            begin
		state <= 0;
		ct_valid_out <= 1'b0;
		ctr <= 0;
		rst_internal <= 0;
		cii_IV_vld <= 0;
		cii_ctl_vld <= 0;
		dii_data_size <= 0;
		dii_data_vld <= 0;
		dii_data <= 0;
		dii_last_word <= 0;

	end
	else begin
		case (state)
		s0: begin // wait for start signal
			if (start == 1'b1) begin
				state <= s1;
				ctr <= 0;
			end
		end

		// initialize module
	    s1: begin
			rst_internal <= 1;
			state <= s2;
		end
	    s2: begin // reset high for 10 CC
			if (ctr == 10) begin
				rst_internal <= 0;
				state <= s3;
			end else begin 
				ctr <= ctr + 1;
			end
		end 
        s3: begin // valid high
			cii_ctl_vld <= 1'b1;
			state <= s4;
		end
	    s4: begin // valid low (pulse)
			cii_ctl_vld <= 1'b0;
			state <= s5;
	   end 
		s5: begin // sending Initial Vector
			cii_IV_vld <= 1'b1;
			dii_data <= iv;
			state <= s6;

		end
		s6: begin

			if(dii_data_not_ready == 0) begin
				state <= s7;
			end else begin
				state <= s6;
			end
		end
		s7: begin
			cii_IV_vld <= 1'b0;
			state <= s8;		
		end
		
		// sending AAD
		s8: begin
			dii_data_vld  <= 1'b1;	
			dii_data_size <= 4'd15;
			dii_data <= 128'b0;
			dii_data_type <= 1'b1;
			dii_last_word <= 1'b0;
			
			state <= s9;
		end

		s9: begin
			dii_data_vld  <= 1'b0;
			state <= s10;
		end 
		
		s10: begin		
			if(dii_data_not_ready == 0) begin
					state <= s11;
			end else begin
					state <= s10;
			end
		end
	
		s11: begin
			// sending text
			dii_data_vld  <= 1'b1;
			dii_data_size <= 4'd15;
			dii_data      <= input_pc;
			dii_data_type <= 1'b0; 
			dii_last_word <= 1'b1;
			state <= s12;

		end
		s12: begin
			dii_data_vld  <= 1'b0;
			state <= s14;
		end
		s14: begin
			if(ct_valid == 1) begin
					state <= s15;
			end else begin
					state <= s14;
			end
		end
		s15: begin
			Out_data_final <= Out_data;
			ct_valid_out <= 1'b1;
			
			state <= s0;
		end
	endcase
	end
end


gcm_aes_v0 aes2_gcm_top(
	.clk(clk),
	.rst(rst_internal),

	// data input interface
	.dii_data(dii_data),  // i/128-bit data input
	.dii_data_vld(dii_data_vld),    // i/data valid
	.dii_data_type(dii_data_type),   // i/data type
	.dii_last_word(dii_last_word),   // i/last word
	.dii_data_not_ready(dii_data_not_ready), // o/data not ready = !(ready)
	.dii_data_size(dii_data_size),      // i/size of input

	// control input interface
	.cii_ctl_vld(cii_ctl_vld), // i/cii_ctl_vld signal
	.cii_IV_vld(cii_IV_vld),       // i/valid input signal   
	.cii_K(cii_K),    //  i/key input

	// data output interfact
	.Out_data(Out_data),          // o/output data
	.Out_vld(ct_valid),     // o/output valid
	.Out_data_size(Out_data_size),       // o/output size
	.Out_last_word(Out_last_word),         // o/output_last_word

	// tag output interface
	.Tag_vld(t_v)             // o/tag_vld
);


endmodule
// File:   rst_wrapper.sv
module rst_wrapper #(
    parameter int unsigned AXI_ADDR_WIDTH = 64,
    parameter int unsigned AXI_DATA_WIDTH = 64,
    parameter int unsigned AXI_ID_WIDTH   = 10
)(
           clk_i,
           rst_ni,
           reglk_ctrl_i,
           acct_ctrl_i,
           debug_mode_i,
           axi_req_i, 
           axi_resp_o,
		   
		   rst_1,
		   rst_2,
		   rst_3,
		   rst_4,
		   rst_5,
		   rst_6,
		   rst_7,
		   rst_8,
		   rst_9,
		   rst_10,
		   rst_11,
		   rst_13
       );

    input  logic                   clk_i;
    input  logic                   rst_ni;
    input logic [7 :0]             reglk_ctrl_i; // register lock values
    input logic                    acct_ctrl_i;
    input logic                    debug_mode_i;
    input  ariane_axi::req_t       axi_req_i;
    output ariane_axi::resp_t      axi_resp_o;

	output logic rst_1;
	output logic rst_2;
	output logic rst_3;
	output logic rst_4;
	output logic rst_5;
	output logic rst_6;
	output logic rst_7;
	output logic rst_8;
	output logic rst_9;
	output logic rst_10;
	output logic rst_11;
	output logic rst_13;

	logic rst_12;

	// internal signals
	logic start;

	logic [4:0]  rst_id;
	logic [13:0] rst_mem;

	// reset logic: if start is high, set to rst memory, otherwise keep at default
	assign rst_1 = rst_mem[1]; // AES0
	assign rst_2 = rst_mem[2]; // AES1
	assign rst_3 = rst_mem[3]; // SHA256
	assign rst_4 = rst_mem[4]; // HMAC
	assign rst_5 = rst_mem[5]; // PKT
	assign rst_6 = rst_mem[6]; // ACCT
	assign rst_7 = rst_mem[7]; // UART
	assign rst_8 = rst_mem[8]; // DMA
	assign rst_9 = rst_mem[9]; // REGLK
	assign rst_10 = rst_mem[10]; // RNG
	assign rst_11 = rst_mem[11]; // AES2
	assign rst_12 = rst_mem[12]; // RST_CTRL
	assign rst_13 = rst_mem[13]; // RSA

// rst vector logic
always @(posedge clk_i) begin
	if (~rst_ni || rst_12) begin
			rst_mem <= 0;
	end else if (start) begin
		case (rst_id)
			0: // ROM
				rst_mem[0] <= 1;
			1: // AES0
				rst_mem[1] <= 1;
			2: // AES1
				rst_mem[2] <= 1;
			3: // SHA256
				rst_mem[3] <= 1;
			4: // HMAC
				rst_mem[4] <= 1;
			5: // PKT
				rst_mem[5] <= 1;
			6: // ACCT
				rst_mem[6] <= 1;
			7: // UART	
				rst_mem[7] <= 1;
			8: // DMA
				rst_mem[8] <= 1;
			9: // REGLK
				rst_mem[9] <= 1;
			10: // RNG
				rst_mem[10] <= 1;
			11: // AES2
				rst_mem[11] <= 1;
			12: // RST_CTRL - the peripheral itself
				rst_mem[12] <= 1;
			13: // RSA
				rst_mem[13] <= 1;
		endcase
	end else begin
		rst_mem <= 0;
	end
end


// signals from AXI 4 Lite
logic [AXI_ADDR_WIDTH-1:0] address;
logic                      en, en_acct;
logic                      we;
logic [63:0] wdata;
logic [63:0] rdata;

///////////////////////////////////////////////////////////////////////////
    // -----------------------------
    // AXI Interface Logic
    // -----------------------------
    axi_lite_interface #(
        .AXI_ADDR_WIDTH ( AXI_ADDR_WIDTH ),
        .AXI_DATA_WIDTH ( AXI_DATA_WIDTH ),
        .AXI_ID_WIDTH   ( AXI_ID_WIDTH    )   
    ) axi_lite_interface_i (
        .clk_i      ( clk_i      ),
        .rst_ni     ( rst_ni     ),
        .axi_req_i  ( axi_req_i  ),
        .axi_resp_o ( axi_resp_o ),
        .address_o  ( address    ),
        .en_o       ( en_acct    ),
        .we_o       ( we         ),
        .data_i     ( rdata      ),
        .data_o     ( wdata      )
    );

    assign en = en_acct && acct_ctrl_i; 



// Implement APB I/O map to AES interface
// Write side
always @(posedge clk_i)
    begin
		if (~rst_ni || rst_12)
			begin
				start <= 0;
				rst_id <= 0;
			end
        else if(en && we)
            case(address[8:3]) // different signals will have a different address base.
                0:
                    start  <= reglk_ctrl_i[1] ? start  : wdata[0];
				1: 
                    rst_id <= reglk_ctrl_i[1] ? rst_id : wdata[31:0];
                default:
                    ;
            endcase
    end // always @ (posedge wb_clk)

// Implement MD5 I/O memory map interface
// Read side
//always @(~write)
always @(*)
    begin
      rdata = 64'b0; 
      if (en) begin
        case(address[8:3])
            0:
                rdata = reglk_ctrl_i[0] ? 'b0 : {31'b0, start};
        endcase
      end // if
    end // always @ (*)




endmodule
