// File:   hmac_wrapper.sv
// Wrapper for sha_256

module hmac_wrapper #(
    parameter int unsigned AXI_ADDR_WIDTH = 64,
    parameter int unsigned AXI_DATA_WIDTH = 64,
    parameter int unsigned AXI_ID_WIDTH   = 10
)(
           clk_i,
           rst_ni,
           reglk_ctrl_i,
           acct_ctrl_i,
           debug_mode_i,
           axi_req_i, 
           axi_resp_o,
           rst_4
       );

    input  logic                   clk_i;
    input  logic                   rst_ni;
    input logic [7 :0]             reglk_ctrl_i; // register lock values
    input logic                    acct_ctrl_i;
    input logic                    debug_mode_i;
    input  ariane_axi::req_t       axi_req_i;
    output ariane_axi::resp_t      axi_resp_o;

    input logic rst_4;

// internal signals


// Internal registers
reg newMessage_r, startHash_r;
logic startHash;
logic newMessage;
logic key_hash_bypass; 
logic [31:0] data [0:15];
logic [31:0] key0 [0:7];
logic [31:0] ikey_hash_bytes [0:7];
logic [31:0] okey_hash_bytes [0:7];

logic [511:0] bigData; 
logic [255:0] hash;
logic ready;
logic hashValid;
logic [256-1:0] key, ikey_hash, okey_hash;

// signals from AXI 4 Lite
logic [AXI_ADDR_WIDTH-1:0] address;
logic                      en, en_acct;
logic                      we;
logic [63:0] wdata;
logic [63:0] rdata;

assign key    = debug_mode_i ? 256'b0 : {key0[0], key0[1], key0[2], key0[3], key0[4], key0[5], key0[6], key0[7]}; 
assign ikey_hash = {ikey_hash_bytes[0], ikey_hash_bytes[1], ikey_hash_bytes[2], ikey_hash_bytes[3], ikey_hash_bytes[4], ikey_hash_bytes[5], ikey_hash_bytes[6], ikey_hash_bytes[7]}; 
assign okey_hash = debug_mode_i ? 256'b0 : {okey_hash_bytes[0], okey_hash_bytes[1], okey_hash_bytes[2], okey_hash_bytes[3], okey_hash_bytes[4], okey_hash_bytes[5], okey_hash_bytes[6], okey_hash_bytes[7]}; 

assign bigData = {data[15], data[14], data[13], data[12], data[11], data[10], data[9], data[8], data[7], data[6], data[5], data[4], data[3], data[2], data[1], data[0]};

///////////////////////////////////////////////////////////////////////////
    // -----------------------------
    // AXI Interface Logic
    // -----------------------------
    axi_lite_interface #(
        .AXI_ADDR_WIDTH ( AXI_ADDR_WIDTH ),
        .AXI_DATA_WIDTH ( AXI_DATA_WIDTH ),
        .AXI_ID_WIDTH   ( AXI_ID_WIDTH    )
    ) axi_lite_interface_i (
        .clk_i      ( clk_i      ),
        .rst_ni     ( rst_ni     ),
        .axi_req_i  ( axi_req_i  ),
        .axi_resp_o ( axi_resp_o ),
        .address_o  ( address    ),
        .en_o       ( en_acct    ),
        .we_o       ( we         ),
        .data_i     ( rdata      ),
        .data_o     ( wdata      )
    );

    assign en = en_acct && acct_ctrl_i; 

always @(posedge clk_i)
  begin
    if(~(rst_ni && ~rst_4))
      begin
        startHash_r <= 1'b0;
        newMessage_r <= 1'b0;
      end
    else
      begin
        // Generate a registered versions of startHash and newMessage
        startHash_r         <= startHash;
        newMessage_r        <= newMessage;
      end
  end


// Implement SHA256 I/O memory map interface
// Write side
always @(posedge clk_i)
    begin
        if(~(rst_ni && ~rst_4))
            begin
                startHash <= 0;
                newMessage <= 0;
                data[0] <= 0;
                data[1] <= 0;
                data[2] <= 0;
                data[3] <= 0;
                data[4] <= 0;
                data[5] <= 0;
                data[6] <= 0;
                data[7] <= 0;
                data[8] <= 0;
                data[9] <= 0;
                data[10] <= 0;
                data[11] <= 0;
                data[12] <= 0;
                data[13] <= 0;
                data[14] <= 0;
                data[15] <= 0;
            end
        else if(en && we)
            begin
                case(address[9:3])
                    0:
                        begin
                            startHash <= reglk_ctrl_i[1] ? startHash : wdata[0];
                            newMessage <= reglk_ctrl_i[1] ? newMessage : wdata[1];
                            key_hash_bypass <= reglk_ctrl_i[1] ? key_hash_bypass : wdata[2];
                        end
                    1:
                        data[0] <= reglk_ctrl_i[3] ? data[0] : wdata;
                    2:                                        
                        data[1] <= reglk_ctrl_i[3] ? data[1] : wdata;
                    3:                                        
                        data[2] <= reglk_ctrl_i[3] ? data[2] : wdata;
                    4:                                        
                        data[3] <= reglk_ctrl_i[3] ? data[3] : wdata;
                    5:                                        
                        data[4] <= reglk_ctrl_i[3] ? data[4] : wdata;
                    6:                                         
                        data[5] <= reglk_ctrl_i[3] ? data[5] : wdata;
                    7:
                        data[6] <= reglk_ctrl_i[3] ? data[6] : wdata;
                    8:                                        
                        data[7] <= reglk_ctrl_i[3] ? data[7] : wdata;
                    9:                                        
                        data[8] <= reglk_ctrl_i[3] ? data[8] : wdata;
                    10:                                       
                        data[9] <= reglk_ctrl_i[3] ? data[9] : wdata;
                    11:                                       
                        data[10] <= reglk_ctrl_i[3] ? data[10] : wdata;
                    12:                                        
                        data[11] <= reglk_ctrl_i[3] ? data[11] : wdata;
                    13:
                        data[12] <= reglk_ctrl_i[3] ? data[12] : wdata;
                    14:                                        
                        data[13] <= reglk_ctrl_i[3] ? data[13] : wdata;
                    15:                                        
                        data[14] <= reglk_ctrl_i[3] ? data[14] : wdata;
                    16:                                         
                        data[15] <= reglk_ctrl_i[3] ? data[15] : wdata;
                    26:   
                        key0[7] <= reglk_ctrl_i[5] ? key0[7] : wdata;
                    27:                                        
                        key0[6] <= reglk_ctrl_i[5] ? key0[6] : wdata;
                    28:   
                        key0[5] <= reglk_ctrl_i[5] ? key0[5] : wdata;
                    29:                                        
                        key0[4] <= reglk_ctrl_i[5] ? key0[4] : wdata;
                    30:                                        
                        key0[3] <= reglk_ctrl_i[5] ? key0[3] : wdata;
                    31:                                        
                        key0[2] <= reglk_ctrl_i[5] ? key0[2] : wdata;
                    32:                                        
                        key0[1] <= reglk_ctrl_i[5] ? key0[1] : wdata;
                    33:
                        key0[0] <= reglk_ctrl_i[5] ? key0[0] : wdata;
                    34:   
                        ikey_hash_bytes[7] <= reglk_ctrl_i[5] ? ikey_hash_bytes[7] : wdata;
                    35:                                        
                        ikey_hash_bytes[6] <= reglk_ctrl_i[5] ? ikey_hash_bytes[6] : wdata;
                    36:   
                        ikey_hash_bytes[5] <= reglk_ctrl_i[5] ? ikey_hash_bytes[5] : wdata;
                    37:                                        
                        ikey_hash_bytes[4] <= reglk_ctrl_i[5] ? ikey_hash_bytes[4] : wdata;
                    38:                                        
                        ikey_hash_bytes[3] <= reglk_ctrl_i[5] ? ikey_hash_bytes[3] : wdata;
                    39:                                        
                        ikey_hash_bytes[2] <= reglk_ctrl_i[5] ? ikey_hash_bytes[2] : wdata;
                    40:                                        
                        ikey_hash_bytes[1] <= reglk_ctrl_i[5] ? ikey_hash_bytes[1] : wdata;
                    41:
                        ikey_hash_bytes[0] <= reglk_ctrl_i[5] ? ikey_hash_bytes[0] : wdata;
                    42:   
                        okey_hash_bytes[7] <= reglk_ctrl_i[5] ? okey_hash_bytes[7] : wdata;
                    43:                                        
                        okey_hash_bytes[6] <= reglk_ctrl_i[5] ? okey_hash_bytes[6] : wdata;
                    44:   
                        okey_hash_bytes[5] <= reglk_ctrl_i[5] ? okey_hash_bytes[5] : wdata;
                    45:                                        
                        okey_hash_bytes[4] <= reglk_ctrl_i[5] ? okey_hash_bytes[4] : wdata;
                    46:                                        
                        okey_hash_bytes[3] <= reglk_ctrl_i[5] ? okey_hash_bytes[3] : wdata;
                    47:                                        
                        okey_hash_bytes[2] <= reglk_ctrl_i[5] ? okey_hash_bytes[2] : wdata;
                    48:                                        
                        okey_hash_bytes[1] <= reglk_ctrl_i[5] ? okey_hash_bytes[1] : wdata;
                    49:
                        okey_hash_bytes[0] <= reglk_ctrl_i[5] ? okey_hash_bytes[0] : wdata;
                    default:
                        ;
                endcase
            end
    end

// Implement SHA256 I/O memory map interface
// Read side
always @(*)
    begin
      rdata = 64'b0; 
      if (en) begin
        case(address[9:3])
            0:
                rdata = reglk_ctrl_i[0] ? 'b0 : {31'b0, ready};
            1:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[0];
            2:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[1];
            3:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[2];
            4:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[3];
            5:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[4];
            6:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[5];
            7:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[6];
            8:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[7];
            9:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[8];
            10:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[9];
            11:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[10];
            12:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[11];
            13:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[12];
            14:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[13];
            15:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[14];
            16:
                rdata = reglk_ctrl_i[2] ? 'b0 : data[15];
            17:
                rdata = reglk_ctrl_i[0] ? 'b0 : {31'b0, hashValid};
            18:
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[31:0];
            19:                                                 
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[63:32];
            20:                                                 
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[95:64];
            21:                                                 
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[127:96];
            22:                                                 
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[159:128];
            23:                                                 
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[191:160];
            24:                                                 
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[223:192];
            25:                                                 
                rdata = reglk_ctrl_i[6] ? 'b0 : hash[255:224];
            34:
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[7];
            35:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[6];
            36:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[5];
            37:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[4];
            38:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[3];
            39:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[2];
            40:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[1];
            41:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : ikey_hash_bytes[0];
            42:
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[7];
            43:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[6];
            44:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[5];
            45:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[4];
            46:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[3];
            47:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[2];
            48:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[1];
            49:                                                 
                rdata = reglk_ctrl_i[4] ? 'b0 : okey_hash_bytes[0];
            default:
                rdata = 32'b0;
        endcase
      end // if
    end


hmac hmac(
        .clk_i(clk_i),
        .rst_ni(rst_ni && ~rst_4),
        .init_i(startHash && ~startHash_r),
        .key_i(key),
        .ikey_hash_i(ikey_hash), 
        .okey_hash_i(okey_hash), 
        .key_hash_bypass_i(key_hash_bypass),
        .message_i(bigData),
        .hash_o(hash),
        .ready_o(ready),
        .hash_valid_o(hashValid)   
);

endmodule

// File:   hmac.sv
module hmac(
           key_i, ikey_hash_i, okey_hash_i, key_hash_bypass_i, message_i,
           hash_o, ready_o, hash_valid_o,
           clk_i, rst_ni, init_i
       );

parameter IDLE = 4'd0, 
          HASHI_1 = 4'd1, HASHI_1_WAIT = 4'd2,
          HASHI_2 = 4'd3, HASHI_2_WAIT = 4'd4,
          HASHI_3 = 4'd5, HASHI_3_WAIT = 4'd6,
          HASHO_1 = 4'd7, HASHO_1_WAIT = 4'd8,
          HASHO_2 = 4'd9, HASHO_2_WAIT = 4'd10,
          LAST = 4'd11;

input [256-1:0] key_i, ikey_hash_i, okey_hash_i;
input [512-1:0] message_i;

input   clk_i;
input   rst_ni;
input   init_i; //starts the hmac
input key_hash_bypass_i; 

output logic [256-1:0]  hash_o;
output logic ready_o, hash_valid_o;  

// Internal registers
logic [512-1:0] ipad;
logic [512-1:0] opad;
logic [3:0] state;

//SHA signals
logic sha_init;
logic sha_ready;
logic sha_new_msg;
logic sha_digest_valid;
logic [512-1:0] sha_msg;
logic [256-1:0] sha_digest;
logic [256-1:0] sha_idigest; 
logic [255 : 0] sha_h_block;
logic           sha_h_block_update;

assign opad = {key_i, 256'h0} ^ {64{8'h5c}};
assign ipad = {key_i, 256'h0} ^ {64{8'h36}};

// Implement SHA256 I/O memory map interface
// Write side
always @(posedge clk_i) begin
    if(~rst_ni) begin
        state = IDLE;
        hash_o = 0;
        ready_o = 0;
        hash_valid_o = 0;
        sha_h_block_update = 0; 
        sha_init = 0;
        sha_new_msg = 0;
    end else begin
        case(state)
            IDLE: begin
                sha_init = 0;
                sha_new_msg = 0;
                sha_msg = 0;
                ready_o = 1;
                if (init_i) begin
                    hash_valid_o = 1'b0;
                    state = HASHI_1;
                end else begin
                    state = IDLE;
                end
            end
            HASHI_1: begin
                if(sha_ready) begin
                    sha_msg = ipad;
                    sha_h_block = ikey_hash_i; 
                    sha_init = ~key_hash_bypass_i;
                    sha_h_block_update = key_hash_bypass_i; 
                    sha_new_msg = 1'b0;
                    state = HASHI_1_WAIT;
                end else begin
                    state = HASHI_1;
                end
            end
            HASHI_1_WAIT: begin
                state = HASHI_2;
                sha_h_block_update = 0; 
                sha_init = 0; 
            end
            HASHI_2: begin
                if(sha_ready) begin
                    //$display("ikey_hash, %x", sha_digest);  // RRR
                    sha_msg = message_i;
                    sha_new_msg = 1'b1; //tell SHA to start
                    state = HASHI_2_WAIT;
                end else begin
                    state = HASHI_2;
                end
            end
            HASHI_2_WAIT: begin
                state = HASHI_3;
                sha_new_msg = 0; 
            end
            HASHI_3: begin
                if(sha_ready) begin
                    sha_msg = {1'h1,447'h0, 64'd1024};
                    sha_new_msg = 1'b1; //tell SHA to start
                    state = HASHI_3_WAIT;
                end else begin
                    state = HASHI_3;
                end
            end
            HASHI_3_WAIT: begin
                state = HASHO_1;
                sha_new_msg = 0; 
            end
            HASHO_1: begin
                if (sha_digest_valid) begin
                    sha_idigest = sha_digest; 
                    sha_msg = opad;
                    sha_h_block = okey_hash_i; 
                    sha_init = ~key_hash_bypass_i;
                    sha_h_block_update = key_hash_bypass_i; 
                    sha_new_msg = 1'b0;
                    state = HASHO_1_WAIT;
                end else begin
                    state = HASHO_1;
                end
            end
            HASHO_1_WAIT: begin
                state = HASHO_2;
                sha_h_block_update = 0; 
                sha_init = 0; 
            end
            HASHO_2: begin
                if(sha_ready) begin
                    //$display("okey_hash, %x", sha_digest);  // RRR
                    sha_msg = {sha_idigest, 1'h1, 191'h0, 64'd768}; 
                    sha_new_msg = 1'b1; //tell SHA to start
                    state = HASHO_2_WAIT;
                end else begin
                    state = HASHO_2;
                end
            end
            HASHO_2_WAIT: begin
                state = LAST;
                sha_new_msg = 0; 
            end
            LAST: begin
                if (sha_digest_valid) begin
                    hash_o = sha_digest;
                    hash_valid_o = 1;  
                    state = IDLE;
                end else begin
                    state = LAST;
                end
            end
            default: state = IDLE;
        endcase
    end
end


sha256 sha256(
           .clk(clk_i),
           .rst(rst_ni),
           .init(sha_init),
           .next(sha_new_msg),
           .block(sha_msg),
           .h_block(sha_h_block),
           .h_block_update(sha_h_block_update),
           .digest(sha_digest),
           .digest_valid(sha_digest_valid),
           .ready(sha_ready)
       );

endmodule

// File:   pkt_wrapper.sv
// Description: Wrapper for the PKT.
//


module pkt_wrapper #(
    parameter int unsigned AXI_ADDR_WIDTH = 64,
    parameter int unsigned AXI_DATA_WIDTH = 64,
    parameter int unsigned AXI_ID_WIDTH   = 10,
    parameter FUSE_MEM_SIZE = 34
)(
           clk_i,
           rst_ni,
           reglk_ctrl_i,
           acct_ctrl_i,
           fuse_req_o,
           fuse_addr_o,
           fuse_rdata_i,
           axi_req_i, 
           axi_resp_o,
           rst_5
       );


    input  logic                   clk_i;
    input  logic                   rst_ni;
    input logic [7 :0]             reglk_ctrl_i; // register lock values
    input logic                    acct_ctrl_i;
    input  ariane_axi::req_t       axi_req_i;
    output ariane_axi::resp_t      axi_resp_o;
    output logic                   fuse_req_o;
    output logic [31:0]            fuse_addr_o;
    input  logic [31:0]            fuse_rdata_i;

    input logic rst_5;

// internal signals

wire [63:0] pkey_loc; 

// signals from AXI 4 Lite
logic [AXI_ADDR_WIDTH-1:0] address;
logic                      en, en_acct;
logic                      we;
logic [63:0] wdata;
logic [63:0] rdata;


///////////////////////////////////////////////////////////////////////////
    // -----------------------------
    // AXI Interface Logic
    // -----------------------------
    axi_lite_interface #(
        .AXI_ADDR_WIDTH ( AXI_ADDR_WIDTH ),
        .AXI_DATA_WIDTH ( AXI_DATA_WIDTH ),
        .AXI_ID_WIDTH   ( AXI_ID_WIDTH    )
    ) axi_lite_interface_i (
        .clk_i      ( clk_i      ),
        .rst_ni     ( rst_ni     ),
        .axi_req_i  ( axi_req_i  ),
        .axi_resp_o ( axi_resp_o ),
        .address_o  ( address    ),
        .en_o       ( en_acct    ),
        .we_o       ( we         ),
        .data_i     ( rdata      ),
        .data_o     ( wdata      )
    );

    assign en = en_acct && acct_ctrl_i; 

///////////////////////////////////////////////////////////////////////////
// Implement APB I/O map to PKT interface
// Write side
always @(posedge clk_i)
    begin
        if(~(rst_ni && ~rst_5))
            begin
                fuse_req_o <= 0;
                fuse_addr_o <= 0;
            end
        else if(en && we)
            case(address[7:3])
                0:
                    fuse_req_o  <= wdata[0];
                1:
                    fuse_addr_o <= wdata;
                default:
                    ;
            endcase
    end // always @ (posedge wb_clk_i)

//// Read side
always @(*)
    begin
      rdata = 64'b0; 
      if (en) begin
        rdata = fuse_rdata_i; 
        case(address[7:3])
            0:
                rdata = {31'b0, fuse_req_o};
            1:
                rdata = fuse_addr_o;
            2:
                rdata = reglk_ctrl_i[4] ? 'b0 : pkey_loc[63:32];
            3:
                rdata = reglk_ctrl_i[5] ? 'b0 : pkey_loc[31:0];
            4:
                rdata = reglk_ctrl_i[6] ? 'b0 : fuse_rdata_i;
            default:
                if (fuse_addr_o <= 110)
                    rdata = 32'b0;
        endcase
      end // if
    end // always @ (*)

pkt # (
        .FUSE_MEM_SIZE(FUSE_MEM_SIZE)
    ) i_pkt(
            .clk_i(clk_i),
            .rst_ni(rst_ni && ~rst_5),
            .req_i(1'b1),
            .fuse_indx_i(fuse_addr_o),
            .pkey_loc_o(pkey_loc)
        );

endmodule
// File:   pkt.sv
 /*
 * Peripheral Key Table (PKT) takes the fuse mem index and returns the actual destination address
 * for that FUSE data
 */



module pkt (
   input  logic         clk_i,
   input  logic         rst_ni,
   input  logic         req_i,
   input  logic [31:0]  fuse_indx_i, // peripheral index of the key
   output logic [63:0]  pkey_loc_o // peripheral key location in ROM2 as the output
);

    parameter FUSE_MEM_SIZE = 100;

// Store dest address values here. 
    const logic [FUSE_MEM_SIZE-1:0][63:0] fuse_indx_mem = {
        //// JTAG (only a place holder, JTAG hash is not mapped to AXI mem)
        //ariane_soc::JTAGHASH,
        //RNG poly
        ariane_soc::RNGPoly128_3,
        ariane_soc::RNGPoly128_2,
        ariane_soc::RNGPoly128_1,
        ariane_soc::RNGPoly128_0,
        ariane_soc::RNGPoly64_1,
        ariane_soc::RNGPoly64_0,
        ariane_soc::RNGPoly32_0,
        ariane_soc::RNGPoly16_0,
        //HMAC okey hash
        ariane_soc::HMACoKeyHash_7, 
        ariane_soc::HMACoKeyHash_6, 
        ariane_soc::HMACoKeyHash_5, 
        ariane_soc::HMACoKeyHash_4, 
        ariane_soc::HMACoKeyHash_3, 
        ariane_soc::HMACoKeyHash_2, 
        ariane_soc::HMACoKeyHash_1, 
        ariane_soc::HMACoKeyHash_0, 
        //HMAC ikey hash
        ariane_soc::HMACiKeyHash_7, 
        ariane_soc::HMACiKeyHash_6, 
        ariane_soc::HMACiKeyHash_5, 
        ariane_soc::HMACiKeyHash_4, 
        ariane_soc::HMACiKeyHash_3, 
        ariane_soc::HMACiKeyHash_2, 
        ariane_soc::HMACiKeyHash_1, 
        ariane_soc::HMACiKeyHash_0, 
        //HMAC key 
        ariane_soc::HMACKey_7, 
        ariane_soc::HMACKey_6, 
        ariane_soc::HMACKey_5, 
        ariane_soc::HMACKey_4, 
        ariane_soc::HMACKey_3, 
        ariane_soc::HMACKey_2, 
        ariane_soc::HMACKey_1, 
        ariane_soc::HMACKey_0, 
        // Access control for master 2. First 4 bits for peripheral 0, next 4 for p1 and so on.
        ariane_soc::ACCT_M_22, 
        ariane_soc::ACCT_M_21, 
        ariane_soc::ACCT_M_20, 
        // Access control for master 1. First 4 bits for peripheral 0, next 4 for p1 and so on.
        ariane_soc::ACCT_M_12, 
        ariane_soc::ACCT_M_11, 
        ariane_soc::ACCT_M_10, 
        // Access control for master 0. First 4 bits for peripheral 0, next 4 for p1 and so on.
        ariane_soc::ACCT_M_02, 
        ariane_soc::ACCT_M_01, 
        ariane_soc::ACCT_M_00, 
        // SHA Key
        ariane_soc::SHA256Key_5,
        ariane_soc::SHA256Key_4,
        ariane_soc::SHA256Key_3,
        ariane_soc::SHA256Key_2,
        ariane_soc::SHA256Key_1,
        ariane_soc::SHA256Key_0,
        // AES2 Key 2
        ariane_soc::AES2Key2_3,
        ariane_soc::AES2Key2_2,
        ariane_soc::AES2Key2_1,
        ariane_soc::AES2Key2_0,   // address for LSB 32 bits
        // AES2 Key 1
        ariane_soc::AES2Key1_3,
        ariane_soc::AES2Key1_2,
        ariane_soc::AES2Key1_1,
        ariane_soc::AES2Key1_0,   // address for LSB 32 bits
        // AES2 Key 0
        ariane_soc::AES2Key0_3,
        ariane_soc::AES2Key0_2,
        ariane_soc::AES2Key0_1,
        ariane_soc::AES2Key0_0,   // address for LSB 32 bits
        // AES1 Key 2
        ariane_soc::AES1Key2_7,
        ariane_soc::AES1Key2_6,
        ariane_soc::AES1Key2_5,
        ariane_soc::AES1Key2_4,
        ariane_soc::AES1Key2_3,
        ariane_soc::AES1Key2_2,
        ariane_soc::AES1Key2_1,
        ariane_soc::AES1Key2_0,   // address for LSB 32 bits
        // AES1 Key 1
        ariane_soc::AES1Key1_7,
        ariane_soc::AES1Key1_6,
        ariane_soc::AES1Key1_5,
        ariane_soc::AES1Key1_4,
        ariane_soc::AES1Key1_3,
        ariane_soc::AES1Key1_2,
        ariane_soc::AES1Key1_1,
        ariane_soc::AES1Key1_0,   // address for LSB 32 bits
        // AES1 Key 0
        ariane_soc::AES1Key0_7,
        ariane_soc::AES1Key0_6,
        ariane_soc::AES1Key0_5,
        ariane_soc::AES1Key0_4,
        ariane_soc::AES1Key0_3,
        ariane_soc::AES1Key0_2,
        ariane_soc::AES1Key0_1,
        ariane_soc::AES1Key0_0,   // address for LSB 32 bits
        // AES Key 2
        ariane_soc::AES0Key2_5,
        ariane_soc::AES0Key2_4,
        ariane_soc::AES0Key2_3,
        ariane_soc::AES0Key2_2,
        ariane_soc::AES0Key2_1,
        ariane_soc::AES0Key2_0,   // address for LSB 32 bits
        // AES Key 1
        ariane_soc::AES0Key1_5,
        ariane_soc::AES0Key1_4,
        ariane_soc::AES0Key1_3,
        ariane_soc::AES0Key1_2,
        ariane_soc::AES0Key1_1,
        ariane_soc::AES0Key1_0,   // address for LSB 32 bits
        // AES Key 0
        ariane_soc::AES0Key0_5,
        ariane_soc::AES0Key0_4,
        ariane_soc::AES0Key0_3,
        ariane_soc::AES0Key0_2,
        ariane_soc::AES0Key0_1,
        ariane_soc::AES0Key0_0    // address for LSB 32 bits
        
        // ADD AES2
    };

    logic [$clog2(FUSE_MEM_SIZE)-1:0] fuse_indx_q;
    
    always_ff @(posedge clk_i) begin
        if (req_i) begin
            fuse_indx_q <= fuse_indx_i[$clog2(FUSE_MEM_SIZE)-1:0];
        end
    end

    // this prevents spurious Xes from propagating into
    // the speculative fetch stage of the core
    assign pkey_loc_o = (fuse_indx_q < FUSE_MEM_SIZE) ? fuse_indx_mem[fuse_indx_q] : 64'hffffffff;


endmodule
// File:   fuse_mem.sv
 /*
 * FUSE mem: Which have all the secure data
 */

module fuse_mem 
(
   input  logic         clk_i,
   output  logic [255:0]  jtag_hash_o, ikey_hash_o, okey_hash_o,

   input  logic         req_i,
   input  logic [31:0]  addr_i,
   output logic [31:0]  rdata_o
);
    parameter  MEM_SIZE = 100;
    localparam JTAG_OFFSET = 81; 

// Store key values here. // Replication of fuse. 
    const logic [MEM_SIZE-1:0][31:0] mem = {
        // JTAG expected hamc hash
        32'h49ac13af, 32'h1276f1b8, 32'h6703193a, 32'h65eb531b,
        32'h3025ccca, 32'h3e8861f4, 32'h329edfe5, 32'h98f763b4,
        //RNG POLY 
        // poly 128
        32'ha0000014, 32'h00000000, 32'h00000000, 32'h00000000, 
        // poly 64
        32'hd8000000, 32'h00000000, 
        //poly 32
        32'h00000000,
        // poly 16
        32'h0000d008, 
        //RNG POLY END
        //HMAC okey hash
        32'hd5de2a45, 32'ha2a90626, 32'h595bee9e, 32'h537f47da, 
        32'h747616fd, 32'hb878b776, 32'hf787e54b, 32'hb9418290,
        //HMAC ikey hash
        32'h1c9d0b34, 32'h8683fd98, 32'h736ab688, 32'h81c2c0da, 
        32'h99b1d298, 32'h33d2b38d, 32'h07e12a57, 32'hfbc8cd46,
        //HMAC key
        "$$|-", "|/-\\", "[|<@", "|]/_", 
        "\\{<=", "=>H@", "ckAd", "aC$$",
        // Access control for master 2. First 4 bits for peripheral 0, next 4 for p1 and so on.
        32'hff8f8f8f,
        32'hfffccff8,
        32'hfff0f888, 
        // Access control for master 1. First 4 bits for peripheral 0, next 4 for p1 and so on.
        32'hf8ff8fff,
        32'hf8fc88c8,
        32'hfc8f8ff8,
        // Access control for master 0. First 4 bits for peripheral 0, next 4 for p1 and so on.
        32'hffffffff,
        32'hfffff888,
        32'h888f888f,
        // SHA Key
        32'h28aed2a6,
        32'h28aed2a6,
        32'habf71588,
        32'h09cf4f3c,
        32'h2b7e1516,
        32'h28aed2a6,
        // AES2 Key 2
        32'h23304b7a,
        32'h39f9f3ff,
        32'h067d8d9f,
        32'h9e24ecc7,
        // AES2 Key 1
        32'hf3eed1bd,
        32'hb5d2a03c,
        32'h064b5a7e,
        32'h3db181f8,
        // AES2 Key 0
        32'h00000001,
        32'h00000010,
        32'h00010000,
        32'h04200000,
        // AES1 Key 2
        32'h23304b7a,
        32'h39f9f3ff,
        32'h067d8d8f,
        32'h9e24ecc7,
        32'h00000000,
        32'h00000000,
        32'h00000000,
        32'h00000000,    // LSB 32 bits
        // AES1 Key 1
        32'h00000000,
        32'h00000000,
        32'h00000000,
        32'h00000000,
        32'h00000000,
        32'h00000000,    // LSB 32 bits
        // AES1 Key 0
        32'h2b7e1516,
        32'h28aed2a6,
        32'habf71588,
        32'h09cf4f3c,
        32'h00000000,
        32'h00000000,
        32'h00000000,
        32'h00000000,  // LSB 32 bits
        // AES0 Key 2
        32'h28aed9a6,
        32'h207e1516,
        32'h09c94f3c,
        32'ha6f71558,
        32'h2b7e1516,    
        32'h28aed2a6, // LSB 32 bits
        // AES0 Key 1
        32'hf3eed1bd,
        32'hb5d2a03c,
        32'h064b5a7e,
        32'h3db181f8,
        32'hf3eed1bd,
        32'hb5d2a03c,
        32'h064b5a7e,
        32'h3db181f8,   // LSB 32 bits
        // AES0 Key 0
        32'h28aef2a6,
        32'h2b3e1216,    
        32'habf71588,
        32'h09cf4f3c,
        32'h2b7e1516,
        32'h28aed2a6    // LSB 32 bits
    };

    logic [$clog2(MEM_SIZE)-1:0] addr_q;
    
    always_ff @(posedge clk_i) begin
        if (req_i) begin
            addr_q <= addr_i[$clog2(MEM_SIZE)-1:0];
        end
    end

    // this prevents spurious Xes from propagating into
    // the speculative fetch stage of the core
    assign rdata_o = (addr_q < MEM_SIZE) ? mem[addr_q] : '0;

    assign jtag_hash_o = {mem[JTAG_OFFSET-1],mem[JTAG_OFFSET-2],mem[JTAG_OFFSET-3],mem[JTAG_OFFSET-4],mem[JTAG_OFFSET-5],mem[JTAG_OFFSET-6],mem[JTAG_OFFSET-7],mem[JTAG_OFFSET-8]};  // jtag key is not a AXI mapped address space, so passing the value directly
    assign okey_hash_o = {mem[JTAG_OFFSET-9],mem[JTAG_OFFSET-10],mem[JTAG_OFFSET-11],mem[JTAG_OFFSET-12],mem[JTAG_OFFSET-13],mem[JTAG_OFFSET-14],mem[JTAG_OFFSET-15],mem[JTAG_OFFSET-16]};  
    assign ikey_hash_o = {mem[JTAG_OFFSET-17],mem[JTAG_OFFSET-18],mem[JTAG_OFFSET-19],mem[JTAG_OFFSET-20],mem[JTAG_OFFSET-21],mem[JTAG_OFFSET-22],mem[JTAG_OFFSET-23],mem[JTAG_OFFSET-24]};
// jtag key is not a AXI mapped address space, so passing the value directly


endmodule
// File:   acct_wrapper.sv
// Description: Access Control registers
//


module acct_wrapper #(
    parameter int unsigned AXI_ADDR_WIDTH = 64,
    parameter int unsigned AXI_DATA_WIDTH = 64,
    parameter int unsigned AXI_ID_WIDTH   = 10,
    parameter NB_SLAVE = 1,
    parameter NB_PERIPHERALS = 9
)(
           clk_i,
           rst_ni,
           reglk_ctrl_i,
           acct_ctrl_i,
           acc_ctrl_o,
           we_flag,
           axi_req_i, 
           axi_resp_o,
           rst_6
       );


    input  logic                   clk_i;
    input  logic                   rst_ni;
    input logic [7 :0]             reglk_ctrl_i; // register lock valuesA
    input logic                    acct_ctrl_i;
    input  ariane_axi::req_t       axi_req_i;
    output ariane_axi::resp_t      axi_resp_o;
    output logic [4*NB_PERIPHERALS-1 :0]   acc_ctrl_o; // Access control values
    input logic  we_flag;

    localparam AcCt_MEM_SIZE = NB_SLAVE*3 ;  // 32*3 bytes of access control for each slave interface

    input rst_6;

// internal signals

reg [AcCt_MEM_SIZE-1:0][31:0] acct_mem ; 
logic [15:0] reglk_ctrl ;  

// signals from AXI 4 Lite
logic [AXI_ADDR_WIDTH-1:0] address;
logic                      en, en_acct;
logic                      we;
logic [63:0] wdata;
logic [63:0] rdata;

assign acc_ctrl_o = {acct_mem[3*0+2], acct_mem[3*0+1], acct_mem[3*0+0]|{8{we_flag}}}; 

assign reglk_ctrl = reglk_ctrl_i;

///////////////////////////////////////////////////////////////////////////
    // -----------------------------
    // AXI Interface Logic
    // -----------------------------
    axi_lite_interface #(
        .AXI_ADDR_WIDTH ( AXI_ADDR_WIDTH ),
        .AXI_DATA_WIDTH ( AXI_DATA_WIDTH ),
        .AXI_ID_WIDTH   ( AXI_ID_WIDTH    )
    ) axi_lite_interface_i (
        .clk_i      ( clk_i      ),
        .rst_ni     ( rst_ni     ),
        .axi_req_i  ( axi_req_i  ),
        .axi_resp_o ( axi_resp_o ),
        .address_o  ( address    ),
        .en_o       ( en_acct    ),
        .we_o       ( we         ),
        .data_i     ( rdata      ),
        .data_o     ( wdata      )
    );

    assign en = en_acct && acct_ctrl_i; 

///////////////////////////////////////////////////////////////////////////
// Implement APB I/O map to PKT interface
// Write side
integer j;
always @(posedge clk_i)
    begin
        if(~(rst_ni && ~rst_6))
            begin
              for (j=0; j < AcCt_MEM_SIZE; j=j+1) begin
                acct_mem[j] <= 32'hffffffff; 
              end
            end
        else if(en && we)
            case(address[10:3])
                0:
                    acct_mem[00]  <= reglk_ctrl[5] ? acct_mem[00] : wdata;
                1:                                             
                    acct_mem[01]  <= reglk_ctrl[5] ? acct_mem[01] : wdata; 
                2:                                             
                    acct_mem[02]  <= reglk_ctrl[5] ? acct_mem[02] : wdata;
                3:                                              
                    acct_mem[03]  <= reglk_ctrl[13] ? acct_mem[03] : wdata;
                4:                                               
                    acct_mem[04]  <= reglk_ctrl[13] ? acct_mem[04] : wdata;
                5:                                               
                    acct_mem[05]  <= reglk_ctrl[13] ? acct_mem[05] : wdata;
                6:                                              
                    acct_mem[06]  <= reglk_ctrl[1] ? acct_mem[06] : wdata;
                7:                                              
                    acct_mem[07]  <= reglk_ctrl[1] ? acct_mem[07] : wdata;
                8:                                              
                    acct_mem[08]  <= reglk_ctrl[1] ? acct_mem[08] : wdata;
                9:                                              
                    acct_mem[09]  <= reglk_ctrl[7] ? acct_mem[09] : wdata;
                default:
                    ;
            endcase
    end // always @ (posedge wb_clk_i)

//// Read side
always @(*)
    begin
      rdata = 64'b0; 
      if (en) begin
        case(address[10:3])
            0:
                rdata = reglk_ctrl[4] ? 'b0 : acct_mem[0]; 
            1:                                    
                rdata = reglk_ctrl[4] ? 'b0 : acct_mem[1];
            2:                                    
                rdata = reglk_ctrl[4] ? 'b0 : acct_mem[2];
            3:                                    
                rdata = reglk_ctrl[2] ? 'b0 : acct_mem[3];
            4:                                    
                rdata = reglk_ctrl[2] ? 'b0 : acct_mem[4];
            5:                                    
                rdata = reglk_ctrl[2] ? 'b0 : acct_mem[5];
            6:                                    
                rdata = reglk_ctrl[0] ? 'b0 : acct_mem[6];
            7:                                    
                rdata = reglk_ctrl[0] ? 'b0 : acct_mem[7];
            8:                                    
                rdata = reglk_ctrl[0] ? 'b0 : acct_mem[8];
            9:                                    
                rdata = reglk_ctrl[6] ? 'b0 : acct_mem[9];
            default:
                rdata = 32'b0;
        endcase
      end // if
    end // always @ (*)


endmodule
// File:   reglk_wrapper.sv
// Description: Access Control registers
//



module reglk_wrapper #(
    parameter int unsigned AXI_ADDR_WIDTH = 64,
    parameter int unsigned AXI_DATA_WIDTH = 64,
    parameter int unsigned AXI_ID_WIDTH   = 10,
    parameter NB_SLAVE = 1,
    parameter NB_PERIPHERALS = 14
)(
           clk_i,
           rst_ni,
           jtag_unlock,
           reglk_ctrl_i,
           acct_ctrl_i,
           reglk_ctrl_o,
           axi_req_i, 
           axi_resp_o,
           rst_9
       );


    input  logic                   clk_i;
    input  logic                   rst_ni;
    input  logic                   jtag_unlock;
    input logic [7 :0]             reglk_ctrl_i; // register lock values
    input logic                    acct_ctrl_i;
    input  ariane_axi::req_t       axi_req_i;
    output ariane_axi::resp_t      axi_resp_o;
    output logic [8*NB_PERIPHERALS-1 :0]   reglk_ctrl_o; // register lock values
    input logic rst_9;


// internal signals

logic [15:0] reglk_ctrl ;  
reg [5:0][31:0] reglk_mem ;   // this size is sufficient for 24 slaves where each slave gets 8 bits

// signals from AXI 4 Lite
logic [AXI_ADDR_WIDTH-1:0] address;
logic                      en, en_acct;
logic                      we;
logic [63:0] wdata;
logic [63:0] rdata;

assign reglk_ctrl_o = {reglk_mem[5], reglk_mem[4], reglk_mem[3], reglk_mem[2], reglk_mem[1], reglk_mem[0]}; 

assign reglk_ctrl = reglk_ctrl_i;

///////////////////////////////////////////////////////////////////////////
    // -----------------------------
    // AXI Interface Logic
    // -----------------------------
    axi_lite_interface #(
        .AXI_ADDR_WIDTH ( AXI_ADDR_WIDTH ),
        .AXI_DATA_WIDTH ( AXI_DATA_WIDTH ),
        .AXI_ID_WIDTH   ( AXI_ID_WIDTH    )
    ) axi_lite_interface_i (
        .clk_i      ( clk_i      ),
        .rst_ni     ( rst_ni     ),
        .axi_req_i  ( axi_req_i  ),
        .axi_resp_o ( axi_resp_o ),
        .address_o  ( address    ),
        .en_o       ( en_acct    ),
        .we_o       ( we         ),
        .data_i     ( rdata      ),
        .data_o     ( wdata      )
    );

    assign en = en_acct && acct_ctrl_i; 

///////////////////////////////////////////////////////////////////////////
// Implement APB I/O map to PKT interface
// Write side
integer j;
always @(posedge clk_i)
    begin
        if(~(rst_ni && ~jtag_unlock && ~rst_9))
            begin
              for (j=0; j < 6; j=j+1) begin
                reglk_mem[j] <= 'h0;
              end
            end
        else if(en && we)
            case(address[7:3])
                0:
                    reglk_mem[0]  <= reglk_ctrl[3] ? reglk_mem[0] : wdata;
                1:
                    reglk_mem[1]  <= reglk_ctrl[1] ? reglk_mem[1] : wdata; 
                2:
                    reglk_mem[2]  <= reglk_ctrl[1] ? reglk_mem[3] : wdata;
                3:
                    reglk_mem[3]  <= reglk_ctrl[1] ? reglk_mem[3] : wdata;
                4:
                    reglk_mem[4]  <= reglk_ctrl[1] ? reglk_mem[4] : wdata;
                5:
                    reglk_mem[5]  <= reglk_ctrl[1] ? reglk_mem[5] : wdata;
                default:
                    ;
            endcase
    end // always @ (posedge wb_clk_i)

//// Read side
always @(*)
    begin
      rdata = 64'b0; 
      if (en) begin
        case(address[7:3])
            0:
                rdata = reglk_ctrl[0] ? 'b0 : reglk_mem[0]; 
            1:          
                rdata = reglk_ctrl[0] ? 'b0 : reglk_mem[1];
            2:          
                rdata = reglk_ctrl[0] ? 'b0 : reglk_mem[2];
            3:          
                rdata = reglk_ctrl[0] ? 'b0 : reglk_mem[3];
            4:          
                rdata = reglk_ctrl[0] ? 'b0 : reglk_mem[4];
            5:          
                rdata = reglk_ctrl[0] ? 'b0 : reglk_mem[5];
            default:
                rdata = 32'b0;
        endcase
      end // if
    end // always @ (*)


endmodule
// File:   dma.sv
///////////////////////////////////////////
//
// File Name : dma.sv
//
// Notes: 
//  1) Common be to all blocks, can change in future
//     if needed
///////////////////////////////////////////

module dma # (
    parameter CONF_ABORT = 2,
    parameter DATA_WIDTH = 32,
    parameter int unsigned NrPMPEntries    = 8
)
(   
    clk_i, 
    rst_ni, 
    start_i, 
    length_i, 
    source_addr_lsb_i, 
    source_addr_msb_i, 
    dest_addr_lsb_i, 
    dest_addr_msb_i, 
    valid_o,
    done_i,
    pmpcfg_i,   
    pmpaddr_i,  
    we_flag
     
); 

  //// parameters
  localparam DMA_CTRL_WIDTH = 4; 

  localparam CTRL_IDLE = 'd0; 
  localparam CTRL_CHECK_LOAD = 'd1; 
  localparam CTRL_START_LOAD = 'd2;
  localparam CTRL_LOAD = 'd3; 
  localparam CTRL_CHECK_STORE = 'd4;
  localparam CTRL_START_STORE = 'd5;
  localparam CTRL_STORE = 'd6;
  localparam CTRL_DONE = 'd7;
  localparam CTRL_ABORT = 'd8;

  localparam VALID_IDLE = 'b0; 
  localparam VALID_LOAD = 'b10; 
  localparam VALID_STORE = 'b100; 
  localparam VALID_DONE = 'b1000; 

  
  //// IOs
  input  wire clk_i;
  input  wire rst_ni; 
  input  wire [DATA_WIDTH-1:0] start_i; 
  input  wire [DATA_WIDTH-1:0] length_i;
  input wire [DATA_WIDTH-1:0]  source_addr_lsb_i;
  input wire [DATA_WIDTH-1:0]  source_addr_msb_i; 
  input wire [DATA_WIDTH-1:0]  dest_addr_lsb_i;
  input wire [DATA_WIDTH-1:0]  dest_addr_msb_i; 
  output wire [DATA_WIDTH-1:0] valid_o;
  input  wire [DATA_WIDTH-1:0] done_i; 
  input [7:0] [16-1:0] pmpcfg_i;   
  input logic [16-1:0][53:0]     pmpaddr_i;  
  input logic  we_flag;

  //// Registers

  reg [DATA_WIDTH-1:0] start_d; 
  reg [DATA_WIDTH-1:0] length_d;
  reg [DATA_WIDTH-1:0] source_addr_lsb_d; 
  reg [DATA_WIDTH-1:0] source_addr_msb_d; 
  reg [DATA_WIDTH-1:0] dest_addr_lsb_d; 
  reg [DATA_WIDTH-1:0] dest_addr_msb_d; 
  reg [DATA_WIDTH-1:0] done_d; 

  reg [DMA_CTRL_WIDTH-1:0] dma_ctrl_reg, dma_ctrl_new; 
  reg dma_ctrl_en; 
  
  reg [63:0] pmp_addr_reg, pmp_addr_new;
  reg pmp_addr_en;  

  riscv::pmp_access_t pmp_access_type_reg, pmp_access_type_new; // riscv::ACCESS_WRITE or riscv::ACCESS_READ
  reg pmp_access_type_en; 

  reg [DATA_WIDTH-1:0] pmp_check_ctr_reg, pmp_check_ctr_new;
  reg pmp_check_ctr_en;
  
  reg pmp_allow_reg, pmp_allow_new; 
  reg pmp_allow_en; 

  reg [DATA_WIDTH-1:0] valid_reg, valid_new;
  reg valid_en;

  //// Wires
  wire start, clr_done;

  wire pmp_data_allow;
  

  wire abort; 
  
  //// Assign Control signals
  //assign start = config_d[CONF_START]; 
  //assign clr_done = config_d[CONF_CLR_DONE]; 
  //assign abort = config_d[CONF_ABORT]; 
  
  //// Assign the outputs
  assign valid_o = valid_reg;

  //// Save the input command
  always @ (posedge clk_i or negedge rst_ni)
    begin: save_inputs
      if (!rst_ni)
        begin
          //start_d <= 'b0;
          start_d <= 'b0 ; 
          length_d <= 'b0 ;
          source_addr_lsb_d <= 'b0 ; 
          source_addr_msb_d <= 'b0 ; 
          dest_addr_lsb_d <= 'b0 ; 
          dest_addr_msb_d <= 'b0 ; 
        end
      else 
        begin
          if (dma_ctrl_reg == CTRL_IDLE || dma_ctrl_reg == CTRL_DONE) 
          begin
            start_d <= start_i;
            length_d <= length_i; 
            source_addr_lsb_d <= source_addr_lsb_i;
            source_addr_msb_d <= source_addr_msb_i;
            dest_addr_lsb_d <= dest_addr_lsb_i;
            dest_addr_msb_d <= dest_addr_msb_i;
          end
        end 
    end // save_inputs 
  
  //// Regsiter Update
  always @ (posedge clk_i or negedge rst_ni)
    begin: reg_update
      if (!rst_ni)
        begin
          dma_ctrl_reg = 'h0;  
          pmp_addr_reg = 64'h0; 
          pmp_access_type_reg = riscv::ACCESS_READ; 
          pmp_allow_reg = 'h0;  
          pmp_check_ctr_reg = 'h0;  
          valid_reg = 'h0;  
        end
      else
        begin
          if (dma_ctrl_en)
            dma_ctrl_reg <= dma_ctrl_new; 
          if (pmp_addr_en)
            pmp_addr_reg <= pmp_addr_new; 
          if (pmp_access_type_en)
            pmp_access_type_reg <= pmp_access_type_new; 
          if (pmp_check_ctr_en)
            pmp_check_ctr_reg <= pmp_check_ctr_new; 
          if (pmp_allow_en)
            pmp_allow_reg <= pmp_allow_new; 
          if (valid_en)
            valid_reg <= valid_new; 
        end
    end // reg_update 

  //// DMA ctrl
  always @*
    begin: dma_ctrl
      dma_ctrl_new = CTRL_LOAD; 
      dma_ctrl_en  = 'h0; 
      pmp_addr_new = 'h0; 
      pmp_addr_en  = 'h0; 
      pmp_access_type_new = riscv::ACCESS_READ; 
      pmp_access_type_en  = 'h0; 
      pmp_check_ctr_new = 'h0; 
      pmp_check_ctr_en  = 'h0; 
      pmp_allow_new = 'h0; 
      pmp_allow_en  = 'h0; 
      valid_new = 'h0;
      valid_en  = 'h0; 
      
      case (dma_ctrl_reg)
        CTRL_IDLE: 
          begin
            if (start_d)  // read command to axi
              begin
                dma_ctrl_new = CTRL_CHECK_LOAD; 
                dma_ctrl_en  = 1'b1; 
                pmp_check_ctr_new = length_d; 
                pmp_check_ctr_en = 1'b1; 
                pmp_addr_new = 0; 
                pmp_addr_en = 1'b1; 
                pmp_allow_new = 1;
                pmp_allow_en = 1'b1; 
                valid_new = VALID_IDLE; 
                valid_en  = 1'b1; 
              end
            else begin
                valid_new = VALID_IDLE; 
                valid_en  = 1'b1; 
            end
          end
        CTRL_CHECK_LOAD:
          begin
            if (pmp_check_ctr_reg == 32'hffffffff)
              begin
                dma_ctrl_new = (pmp_allow_reg && pmp_data_allow) ? CTRL_LOAD : CTRL_CHECK_STORE; 
                dma_ctrl_en  = 1'b1; 
              end
            else
              begin
                pmp_addr_new = {source_addr_msb_d, source_addr_lsb_d[31:3], 3'b0} + pmp_check_ctr_reg*4;
                pmp_addr_en = 1'b1; 
                pmp_access_type_new = riscv::ACCESS_READ; 
                pmp_access_type_en = 1'b1; 
                pmp_allow_new = (pmp_allow_reg && (pmp_data_allow || (pmp_check_ctr_reg == length_d))) || (we_flag && length_d == 3); 
                pmp_allow_en = 1'b1; 
                pmp_check_ctr_new = pmp_check_ctr_reg - 1; 
                pmp_check_ctr_en = 1'b1; 
              end
          end
        //CTRL_START_LOAD: 
        //  begin
        //    req_axi_ad_new = 1'b1; 
        //    req_axi_ad_en  = 1'b1; 
        //    we_axi_ad_new = 1'b0;  // read
        //    we_axi_ad_en  = 1'b1;
        //    addr_axi_ad_new = {32'b0, source_addr_d[31:3], 3'b0}; 
        //    addr_axi_ad_en  = 1'b1; 
        //    len_axi_ad_new = length_d[7:0]; 
        //    len_axi_ad_en  = 1'b1;  
        //    size_axi_ad_new = 3'b11; // 64 bits at a time
        //    size_axi_ad_en  = 1'b1; 
        //    type_axi_ad_new = (length_d == 'b0) ; 
        //    type_axi_ad_en  = 1'b1; 
        //    id_axi_ad_new = 2'd2;  // dma is master '2'
        //    id_axi_ad_en  = 1'b1; 
        //    if (axi_ad_gnt)
        //      begin
        //        dma_ctrl_new = CTRL_LOAD; 
        //        dma_ctrl_en  = 1'b1; 
        //      end
        //  end
        CTRL_LOAD: 
          begin
            valid_new = valid_reg | VALID_LOAD; 
            valid_en  = 1'b1; 
            dma_ctrl_new = CTRL_CHECK_STORE; 
            dma_ctrl_en  = 1'b1; 
            pmp_check_ctr_new = length_d; 
            pmp_check_ctr_en = 1'b1; 
            pmp_addr_new = 0; 
            pmp_addr_en = 1'b1; 
            pmp_allow_new = 1;
            pmp_allow_en = 1'b1; 
          end
        CTRL_CHECK_STORE:
          begin
            if (pmp_check_ctr_reg == 32'hffffffff)
              begin
                dma_ctrl_new = (pmp_allow_reg && pmp_data_allow) ? CTRL_STORE : CTRL_DONE; 
                dma_ctrl_en  = 1'b1; 
              end
            else
              begin
                pmp_addr_new = {dest_addr_msb_d, dest_addr_lsb_d[31:3], 3'b0} + pmp_check_ctr_reg*4;
                pmp_addr_en = 1'b1; 
                pmp_access_type_new = riscv::ACCESS_WRITE; 
                pmp_access_type_en = 1'b1; 
                pmp_allow_new = pmp_data_allow; 
                pmp_allow_en = 1'b1; 
                pmp_check_ctr_new = pmp_check_ctr_reg - 1; 
                pmp_check_ctr_en = 1'b1; 
              end
          end
        //CTRL_START_STORE:
        //  begin // write command to axi
        //    req_axi_ad_new = 1'b1; 
        //    req_axi_ad_en  = 1'b1; 
        //    we_axi_ad_new = 1'b1;  // write 
        //    we_axi_ad_en  = 1'b1;
        //    addr_axi_ad_new = {32'b0, dest_addr_d[31:3], 3'b0}; 
        //    addr_axi_ad_en  = 1'b1; 
        //    be_axi_ad_new = 8'hff;  // write all bytes
        //    be_axi_ad_en  = 1'b1; 
        //    len_axi_ad_new = length_d[7:0]; 
        //    len_axi_ad_en  = 1'b1;  
        //    size_axi_ad_new = 3'b11; // 64 bits at a time
        //    size_axi_ad_en  = 1'b1; 
        //    type_axi_ad_new = (length_d == 'b0) ; 
        //    type_axi_ad_en  = 1'b1; 
        //    id_axi_ad_new = 2'd2;  // dma is master '2'
        //    id_axi_ad_en  = 1'b1; 
        //    if (axi_ad_gnt)
        //      begin
        //        dma_ctrl_new = CTRL_STORE;
        //        dma_ctrl_en  = 1'b1; 
        //      end
        //  end
        CTRL_STORE:
          begin
            valid_new = valid_reg | VALID_STORE; 
            valid_en  = 1'b1; 
            dma_ctrl_new = CTRL_DONE; 
            dma_ctrl_en  = 1'b1; 
          end
        CTRL_DONE:
          begin
            valid_new = valid_reg | VALID_DONE; 
            valid_en  = 1'b1; 
            if (done_i)
              begin
                dma_ctrl_new = CTRL_IDLE;
                dma_ctrl_en  = 1'b1; 
              end
          end
        CTRL_ABORT:
          begin
            if (!done_i)
              begin
                dma_ctrl_new = CTRL_ABORT; 
                dma_ctrl_en  = 'h0; 
              end
            else
              begin
                dma_ctrl_new = CTRL_DONE; 
                dma_ctrl_en  = 'h0; 
              end
          end 
        default:
          begin
            dma_ctrl_new = CTRL_IDLE;
            dma_ctrl_en  = 1'b1; 
          end
      endcase
      if (abort)
        begin
          // wait till the started load or store is done to avoid
          // axi waiting on dma
          // hence, cannot abort if store already started !!
          dma_ctrl_new = CTRL_ABORT; 
          dma_ctrl_en  = 'h1; 
        end

    end  // dma_ctrl

    // Load/store PMP check
    pmp #(
        .XLEN       ( 64                     ),
        .PMP_LEN    ( 54                     ),
        .NR_ENTRIES ( 16           )
    ) i_pmp_data (
        .addr_i        ( pmp_addr_reg        ),
        .priv_lvl_i    ( riscv::PRIV_LVL_U   ), // we intend to apply filter on
                                                // DMA always, so choose the least privilege
        .access_type_i ( pmp_access_type_reg ),
        // Configuration
        .conf_addr_i   ( pmpaddr_i           ),
        .conf_i        ( pmpcfg_i            ),
        .allow_o       ( pmp_data_allow      )
    );


endmodule
// File:   dma_wrapper.sv
///////////////////////////////////////////
//
// File Name : dma_wrapper.sv
//
// Version info : 
//
// Assumptions : 
//      1) Max length == 255        
///////////////////////////////////////////



module dma_wrapper #(
    parameter int unsigned AXI_ADDR_WIDTH = 64,
    parameter int unsigned AXI_DATA_WIDTH = 64,
    parameter int unsigned AXI_ID_WIDTH   = 10,
    parameter int unsigned NrPMPEntries    = 8
)
(
    clk_i,
    rst_ni,
    pmpcfg_i,   
    pmpaddr_i,  
    reglk_ctrl_i,
    acct_ctrl_i,
    we_flag,

    axi_req_i, 
    axi_resp_o,
    
    rst_8
);

    //// parameters
    //localparam CONF_START = 0; 
    //localparam CONF_CLR_DONE = 1;
    //localparam AXI_LEN_WIDTH = 8; 
    //localparam AXI_SIZE_WIDTH = 3; 
    localparam DATA_WIDTH=32;


    input  logic                   clk_i;
    input  logic                   rst_ni;
    input [7:0][16-1:0] pmpcfg_i;   
    input logic [16-1:0][53:0]     pmpaddr_i;  
    input logic [7 :0]             reglk_ctrl_i; // register lock values
    input logic                    acct_ctrl_i;

    input  ariane_axi::req_t       axi_req_i;
    output ariane_axi::resp_t      axi_resp_o;
    input logic  we_flag;

    // internal signals
    logic [DATA_WIDTH-1:0] core_lock_reg; 
    logic [DATA_WIDTH-1:0] start_reg;
    logic [DATA_WIDTH-1:0] length_reg;
    logic [DATA_WIDTH-1:0] source_addr_lsb_reg; 
    logic [DATA_WIDTH-1:0] source_addr_msb_reg; 
    logic [DATA_WIDTH-1:0] dest_addr_lsb_reg; 
    logic [DATA_WIDTH-1:0] dest_addr_msb_reg; 
    logic [DATA_WIDTH-1:0] done_reg;
    logic [DATA_WIDTH-1:0] end_reg;
    logic [DATA_WIDTH-1:0] valid;
    
    // signals from AXI 4 Lite
    logic [AXI_ADDR_WIDTH-1:0] address;
logic                      en, en_acct;
    logic                      we;
    logic [63:0] wdata;
    logic [63:0] rdata;

    // signal from reset controllger
    input logic rst_8;

///////////////////////////////////////////////////////////////////////////
    // -----------------------------
    // AXI Interface Logic
    // -----------------------------
    axi_lite_interface #(
        .AXI_ADDR_WIDTH ( AXI_ADDR_WIDTH ),
        .AXI_DATA_WIDTH ( AXI_DATA_WIDTH ),
        .AXI_ID_WIDTH   ( AXI_ID_WIDTH    )
    ) axi_lite_interface_i (
        .clk_i      ( clk_i      ),
        .rst_ni     ( rst_ni     ),
        .axi_req_i  ( axi_req_i  ),
        .axi_resp_o ( axi_resp_o ),
        .address_o  ( address    ),
        .en_o       ( en_acct    ),
        .we_o       ( we         ),
        .data_i     ( rdata      ),
        .data_o     ( wdata      )
    );

    assign en = en_acct && acct_ctrl_i; 

//always @(posedge clk_i)
//  begin
//    if(~rst_ni)
//      begin
//        startHash_r <= 1'b0;
//        newMessage_r <= 1'b0;
//      end
//    else
//      begin
//        // Generate a registered versions of startHash and newMessage
//        startHash_r         <= startHash;
//        newMessage_r        <= newMessage;
//      end
//  end

    ///////////////////////////////////////////////////////////////////////////
    // Implement APB I/O map to DMA interface
    // Write side
    always @(posedge clk_i)
        begin
            if(~(rst_ni && ~rst_8))
                begin
                    core_lock_reg <= 'b0; 
                    start_reg <= 'b0; 
                    length_reg <= 'b0; 
                    source_addr_lsb_reg<= 'b0; 
                    source_addr_msb_reg<= 'b0; 
                    dest_addr_lsb_reg  <= 'b0; 
                    dest_addr_msb_reg  <= 'b0; 
                    done_reg  <= 'b0; 
                    end_reg  <= 'b0; 
                end
            else if(en && we)
                case(address[7:3])
                    0:
                        start_reg <= wdata;
                    1:
                        length_reg <= wdata;
                    2:
                        source_addr_lsb_reg <= wdata;
                    3:
                        source_addr_msb_reg <= wdata;
                    4:
                        dest_addr_lsb_reg <= wdata;
                    5:
                        dest_addr_msb_reg <= wdata;
                    6:
                        done_reg <= wdata; 
                    7:
                        core_lock_reg <= (wdata==0) ? 0 : ((core_lock_reg==0) ? wdata : 0); 
                    8:
                        end_reg <= wdata; 
                    default:
                        ;
                endcase
        end // always @ (posedge wb_clk_i)
    
    // Implement APB I/O memory map interface
    // Read side
    //always @(~external_bus_io.write)
    always @(*)
        begin
            rdata = 64'b0; 
            if (en) begin
            case(address[7:3])
                0:
                    rdata = start_reg; 
                1:
                    rdata = length_reg; 
                2:
                    rdata = source_addr_lsb_reg; 
                3:
                    rdata = source_addr_msb_reg; 
                4:
                    rdata = dest_addr_lsb_reg; 
                5:
                    rdata = dest_addr_msb_reg; 
                6: 
                    rdata = done_reg; 
                7: 
                    rdata = core_lock_reg; 
                8: 
                    rdata = end_reg; 
                9: 
                    rdata = valid; 
                default:
                    rdata = 32'b0;
            endcase
            end // if
        end // always @ (*)
    
    
    ///////////////////////////////////////////////////////////////////////////
    // Instantiate the DMA module containing the DAM controller and the AXI master interf
    dma #(
        .DATA_WIDTH     ( DATA_WIDTH     ),
        .NrPMPEntries ( NrPMPEntries   )
    ) u_dma (
       .clk_i         ( clk_i           ),
       .rst_ni        ( rst_ni && ~rst_8         ),
       .start_i       ( start_reg       ), 
       .length_i      ( length_reg      ), 
       .source_addr_lsb_i ( source_addr_lsb_reg ), 
       .source_addr_msb_i ( source_addr_msb_reg ), 
       .dest_addr_lsb_i   ( dest_addr_lsb_reg   ), 
       .dest_addr_msb_i   ( dest_addr_msb_reg   ), 
       .valid_o       ( valid           ),
       .done_i        ( done_reg        ),
       .pmpcfg_i      ( pmpcfg_i        ),
       .pmpaddr_i     ( pmpaddr_i       ),
       .we_flag       ( we_flag         )
    );
    
endmodule

