module rng_top(
	input               clk,
	input             rst_n,
	input             load_i,
	input      [127:0]	seed_i,
	input 	   [127:0]	poly128_i,
	input	   [63:0]   poly64_i,
	input	   [31:0]   poly32_i,
	input	   [15:0]   poly16_i,
	output     [63:0]	rand_num_o,
    output              rand_num_valid_o,

    //signal for debug mode
    //seed segment for each entropy source
	output [127:0] seed128_o,
	output [63:0] seed64_o,
	output [31:0] seed32_o,
	output [15:0] seed16_o,

	//rand num segment from each entropy source
	output [15:0] rand_seg128_o,
	output [15:0] rand_seg64_o,
	output [15:0] rand_seg32_o,
	output [15:0] rand_seg16_o,
	output [3:0] cs_state_o
);

//tap location for each lfsr
  wire 	   [127:0]	poly128;
  wire	   [63:0]   poly64;
  wire	   [31:0]   poly32;
  wire	   [15:0]   poly16;

//seed segment for each entropy source
reg [127:0] seed128;
reg [63:0] seed64;
reg [31:0] seed32;
reg [15:0] seed16;

//rand num segments from each entropy source
wire [15:0] rand_seg128;
wire [15:0] rand_seg64;
wire [15:0] rand_seg32;
wire [15:0] rand_seg16;

//local signals
wire load;
wire [127:0] seed;
wire [127:0] entropy128;
wire [63:0] entropy64;
wire [31:0] entropy32;
wire [15:0] entropy16;
wire entropy128_valid;
wire entropy64_valid;
wire entropy32_valid;
wire entropy16_valid;
wire [63:0] rand_num;
wire rand_num_valid;
wire [3:0] cs_state;

//assign value from local signals to ports
assign seed = seed_i;
assign load = load_i;

assign poly128 = poly128_i;
assign poly64 = poly64_i;
assign poly32 = poly32_i;
assign poly16 = poly16_i;

assign rand_num_o = rand_num;
assign rand_num_valid_o = rand_num_valid;


assign seed128_o = seed128;
assign seed64_o = seed64;
assign seed32_o = seed32;
assign seed16_o = seed16;

assign rand_seg128_o = rand_seg128;
assign rand_seg64_o = rand_seg64;
assign rand_seg32_o = rand_seg32;
assign rand_seg16_o = rand_seg16;

assign cs_state_o = cs_state;

reg [1:0] seed_ct;

always @ (posedge clk)
begin
	if (!rst_n)
	begin
		seed_ct <= 2'b0;
	end
	else
	begin
		seed_ct <= seed_ct + 1;
	end
end


always @(*)
begin
	seed128 = seed;
	case(seed_ct)
		0:begin
			seed16 <= seed[127:112];
			seed32 <= seed[127:96];
			seed64 <= seed[127:64];
		end
		1:begin
			seed16 <= seed[111:96];
			seed32 <= seed[111:80];
			seed64 <= seed[111:48];
		end
		2:begin
			seed16 <= seed[95:80];
			seed32 <= seed[95:64];
			seed64 <= seed[95:32];
		end
		3:begin
			seed16 <= seed[79:64];
			seed32 <= seed[79:48];
			seed64 <= seed[79:16];
		end
		default:begin
			seed16 <= 0;
			seed32 <= 0;
			seed64 <= 0;
		end
	endcase // seed_ct
end


rng_cs CS0(
			.clk(clk),
		    .rst_n(rst_n),
		    .entropy128_i(entropy128),
		    .entropy128_valid_i(entropy128_valid),		   
	   	    .entropy64_i(entropy64),
	   	    .entropy64_valid_i(entropy64_valid),
	        .entropy32_i(entropy32),
	        .entropy32_valid_i(entropy32_valid),
	        .entropy16_i(entropy16),
	        .entropy16_valid_i(entropy16_valid),
		    .rand_num_o(rand_num),
    		.rand_num_valid_o(rand_num_valid),
			.rand_seg128_o(rand_seg128),
	    	.rand_seg64_o(rand_seg64),
	    	.rand_seg32_o(rand_seg32),
	    	.rand_seg16_o(rand_seg16),
	    	.cs_state_o(cs_state));


rng_128 RNG128(
			.clk(clk),
			.rst_n(rst_n),
			.load_i(load),
		 	.seed_i(seed128),
			.poly_i(poly128),
			.entropy128_o(entropy128),
    		.entropy128_valid_o(entropy128_valid)
	);

rng_64 RNG64(
			.clk(clk),
			.rst_n(rst_n),
			.load_i(load),
		 	.seed_i(seed64),
			.poly_i(poly64),
			.entropy64_o(entropy64),
    		.entropy64_valid_o(entropy64_valid)
	);

rng_32 RNG32(
			.clk(clk),
			.rst_n(rst_n),
			.load_i(load),
		 	.seed_i(seed32),
			.poly_i(poly32),
			.entropy32_o(entropy32),
    		.entropy32_valid_o(entropy32_valid)
	);

rng_16 RNG16(
			.clk(clk),
			.rst_n(rst_n),
			.load_i(load),
		 	.seed_i(seed16),
			.poly_i(poly16),
			.entropy16_o(entropy16),
    		.entropy16_valid_o(entropy16_valid)
	);

endmodule : rng_top
// File:   inverter.v
`define UPDATING 3'd1
`define CHECK 3'd2
`define HOLDING 3'd3
/*to calculate decryption key 'd' and encryption key 'e' we use extended euclidian algorithm  
i.e                 d * e = 1 mod (phi)
*/
module inverter
#(parameter WIDTH = 1024
    )(
  input [WIDTH-1:0] p,//prime number 1
	input [WIDTH-1:0] q,//prime number 2
	input clk,
	input rst_n,
	output finish,//indicates finish for operation
	output [WIDTH*2-1:0] e,//encryption key
	output [WIDTH*2-1:0] d//decryption key
    );
    
    reg [WIDTH*2-1:0] totient_reg,a,b,y,y_prev;//totient here represents phi
    reg [2:0] state;
    reg [WIDTH*2-1:0] e_reg;
    
    wire [WIDTH*2-1:0] totient = (p-1)*(q-1);
    wire [WIDTH*2-1:0] quotient,b_next;
    wire [WIDTH*2-1:0] y_next = y_prev - quotient * y;
    wire [WIDTH*2-1:0] e_plus3 = e_reg + 2;
    assign finish = (state == `HOLDING) ? 1'b1 : 1'b0;
    assign e = e_reg;
    assign d = (e_reg == 1)? (totient+1) : y_prev;
    
    mod x_mod_y(a,b,b_next,quotient);//divider module
    defparam x_mod_y.WIDTH = WIDTH*2;
    
    always @(posedge clk) begin
        if(!rst_n) begin
            totient_reg <= totient;
            a <= totient;
            b <= 1;
            e_reg <=1;
            y <= 1;
            y_prev <= 0;
            state <= `UPDATING;
        end 
              case(state)
                `UPDATING: begin
                    if(b != 'd0) begin
                        a <= b;
                        b <= b_next;
                        y <= y_next;
                        y_prev <= y;
                        state <= `UPDATING;
                    end
                    else state <= `CHECK;
                 end
                `CHECK: begin
                    if(a == 'd1 && y_prev[WIDTH*2-1] == 1'b0) 
                        state <= `HOLDING;
                    else begin
                         a <= totient_reg;
                         b <= e_plus3;
                         e_reg <= e_plus3;
                         y <= 1;
                         y_prev <= 0;
                         state <= `UPDATING;
                   end
                 end
                `HOLDING: begin
                    end
           endcase 
    end
    
endmodule
// File:   mod.v
module mod
  #(parameter WIDTH=32)(
    input [WIDTH-1:0] a,
    input [WIDTH-1:0] n,
    output [WIDTH-1:0] R,
    output [WIDTH-1:0] Q
    );
   
   reg [WIDTH-1:0] A,N;
   reg [WIDTH:0] p;   
   integer i;
  
   always@ (a or n) begin
       A = a;
       N = n;
       p = 0;
       for(i=0;i < WIDTH;i=i+1) begin 
           p = {p[WIDTH-2:0],A[WIDTH-1]};
           A[WIDTH-1:1] = A[WIDTH-2:0];
           p = p-N;
           if(p[WIDTH-1] == 1)begin
                A[0] = 1'b0;
                p = p + N;   
           end
           else
                A[0] =1'b1;
      end
         
   end    
   
   assign R = p,Q = A;
endmodule
// File:   mod_exp.v
`define UPDATE 2'd1
`define HOLD 2'd2
/* to calculate *** a^b mod n *** we use right to left binary exponentiation (by .BRUCE SCHIENER)
*/
module mod_exp
    #(parameter WIDTH = 1024)(
    input [WIDTH*2-1:0] base,//base here represents (a) 
	input [WIDTH*2-1:0] modulo,//modulo here is modulus (n)
	input [WIDTH*2-1:0] exponent,//exponent here is the power of base (b)
	input clk,
	input rst_n,//resets module
	output finish,//sends finish signal on completion
    output [WIDTH*2-1:0] result
    );
        
    reg [WIDTH*2-1:0] base_reg,modulo_reg,exponent_reg,result_reg;
    reg [1:0] state;
    
    wire [WIDTH*2-1:0] result_mul_base = result_reg * base_reg;
    wire [WIDTH*2-1:0] result_next;
    wire [WIDTH*2-1:0] base_squared = base_reg * base_reg;
    wire [WIDTH*2-1:0] base_next;
    wire [WIDTH*2-1:0] exponent_next = exponent_reg >> 1;
    
    assign finish = (state == `HOLD) ? 1'b1:1'b0;
    assign result = result_reg;
    
    mod base_squared_mod(base_squared,modulo_reg,base_next,);                   //  implementation of 
    defparam base_squared_mod.WIDTH = WIDTH*2;                                  //  right to left 
                                                                                //  binary exponentiation  
    mod result_mul_base_mod (result_mul_base,modulo_reg,result_next,);          //  by.
    defparam result_mul_base_mod.WIDTH = WIDTH*2;                               //  BRUCE SCHIEMER
    
   
    always @(posedge clk) begin
        if(!rst_n) begin                                                         //initialisation of values
            base_reg <= base;
            modulo_reg <= modulo;
            exponent_reg <= exponent;                
            result_reg <= 'd1;
            state <= `UPDATE;
        end
        else case(state)
            `UPDATE: begin
                if (exponent_reg != 'd0) begin
                    if (exponent_reg[0])
                        result_reg <= result_next;
                    base_reg <= base_next;
                    exponent_reg <= exponent_next;
                    state <= `UPDATE;
                end
                else state <= `HOLD;
            end
            
           `HOLD: begin
                end
       endcase
    end
endmodule
// File:   rsa_top.v
module rsa_top
#(parameter WIDTH=1024
	)(
    input clk,//system wide clock
    input rst_n,//resets inverter module
    input rst1_n,//resets modular exponentiation module
    input encrypt_decrypt_i,//1 for encryption and 0 for decryption
    input [WIDTH-1:0] p_i,q_i, //Input Random Primes
    input [WIDTH*2-1:0] msg_in,//input either message or cipher
    output [WIDTH*2-1:0] msg_out,//output either decrypted message or cipher
    output mod_exp_finish_o//finish signal indicator of mod exp module
    );
    
    wire inverter_finish;
    wire [WIDTH*2-1:0] e,d;
    wire [WIDTH*2-1:0] exponent = encrypt_decrypt_i?e:d;
    wire [WIDTH*2-1:0] modulo = p_i*q_i;
    wire mod_exp_reset  = 1'b0;
    

    //Signla will delay one cycle to module
    //after we set signal value, we need to delay one cycle to reset signal
    reg [WIDTH*2-1:0] exp_reg,msg_reg;
    reg [WIDTH*2-1:0] mod_reg;
    
    always @(posedge clk)begin
         exp_reg <= exponent;
         mod_reg <= modulo;
         msg_reg <= msg_in;
    end
    
    inverter i(p_i,q_i,clk,rst_n,inverter_finish,e,d);
    defparam i.WIDTH = WIDTH;
    mod_exp m(msg_reg,mod_reg,exp_reg,clk,rst1_n,mod_exp_finish_o,msg_out);
    defparam m.WIDTH = WIDTH;
    
endmodule
