// File:   piton_stubs.v
// OpenPiton technology primitive stubs for lint-only/flatten flow
// These are scan flip-flop cells not provided in the open-source flow.

module bw_u1_soffasr_2x (
    input  wire ck, d, r_l, s_l, se, sd,
    output reg  q, so
);
    always @(posedge ck or negedge r_l) begin
        if (!r_l)       q <= 1'b0;
        else if (!s_l)  q <= 1'b1;
        else if (se)    q <= sd;
        else            q <= d;
    end
    assign so = q;
endmodule

module bw_u1_soff_8x (
    input  wire ck, d, se, sd,
    output reg  q, so
);
    always @(posedge ck) begin
        if (se) q <= sd;
        else    q <= d;
    end
    assign so = q;
endmodule

module bw_u1_scanl_2x (
    input  wire ck, sd,
    output reg  so
);
    always @(posedge ck) begin
        so <= sd;
    end
endmodule
